-- BEFORE: email duplicated on every order row (update-anomaly farm)
--   orders(id, customer_id, customer_email, total, created_at)

-- Selected approach: normalize to 3NF, join on read, FK guards the invariant.
BEGIN;
  ALTER TABLE orders
    ADD CONSTRAINT orders_customer_fk
    FOREIGN KEY (customer_id) REFERENCES customers(id);
  -- backfill any orphan rows BEFORE dropping the copy, or the migration lies
  UPDATE customers c SET email = o.customer_email
    FROM orders o WHERE o.customer_id = c.id AND c.email IS NULL;
  ALTER TABLE orders DROP COLUMN customer_email;   -- the redundant fact, gone
COMMIT;

