transactions-atomicity.code:
-- WEAK: two independent commits. A crash here loses $500.
UPDATE accounts SET balance = balance - 500 WHERE id = 'A';  -- commits alone
UPDATE accounts SET balance = balance + 500 WHERE id = 'B';

-- GOLD: one atomic unit of work.
BEGIN;
  UPDATE accounts SET balance = balance - 500 WHERE id = 'A';
  -- Guard the invariant INSIDE the unit, before COMMIT:
  -- a CHECK (balance >= 0) constraint fires here and aborts the whole tx.
  UPDATE accounts SET balance = balance + 500 WHERE id = 'B';
COMMIT;

-- PROOF: force a failure between the two writes, then inspect.
BEGIN;
  UPDATE accounts SET balance = balance - 500 WHERE id = 'A';
  SELECT 1 / 0;          -- simulated crash / deadlock mid-transaction
  UPDATE accounts SET balance = balance + 500 WHERE id = 'B';
COMMIT;                  -- never reached; Postgres aborts the tx
-- SELECT balance FROM accounts WHERE id IN ('A','B');
-- => A and B BOTH unchanged. Zero partial state. Atomicity proven.

