export interface OrderRepository {
  findById(id: string): Promise<Order | null>
  findByCustomer(customerId: string): Promise<Order[]>
  save(order: Order): Promise<void>  // create or update, in one tx
}

export class PgOrderRepository implements OrderRepository {
  constructor(private readonly db: Pool) {}

  async findById(id: string): Promise<Order | null> {
    // amount_cents is the NEW name; callers never see the column
    const { rows } = await this.db.query(
      'SELECT id, customer_id, amount_cents, status FROM orders WHERE id = $1',
      [id],
    )
    return rows[0] ? this.toDomain(rows[0]) : null
  }

  async save(order: Order): Promise<void> {
    await this.db.query('BEGIN')
    try {
      await this.db.query(
        `INSERT INTO orders (id, customer_id, amount_cents, status)
         VALUES ($1,$2,$3,$4)
         ON CONFLICT (id) DO UPDATE SET
           amount_cents = EXCLUDED.amount_cents, status = EXCLUDED.status`,
        [order.id, order.customerId, order.amountCents, order.status],
      )
      await this.db.query('COMMIT')
    } catch (e) {
      await this.db.query('ROLLBACK')
      throw e
    }
  }

  // the mapping seam: row shape -> domain object
  private toDomain(r: OrderRow): Order {
    return new Order(r.id, r.customer_id, r.amount_cents, r.status)
  }
}

